    "extended_commentary": "<p>තුම්හෙ, තෙපි; තිට්ඨථ; සිටිව්; අම්හෙ, අපි; භිය්‍යො, සේ නොහොත් නැවත නැවත; මහෙමසෙ, පුදමු</p><p>ත්වං පුමා, ත්වං ඉත්ථී, ත්වං නපුංසකං; අහං පුමා, අහං ඉත්ථී, අහං නපුංසකං — යන මෙයින් තුම්හ අම්හ ශබ්ද ලිඞ්ගත්‍රයෙහි ම සමාන රූප ඇති බව (අලිඞ්ග බව) හඟවයි (සන්නය).</p>",
