      "padattha_pali": "සබ්බෙසං තුම්හඅම්හසද්දානං සවිභත්තීනං තං මං ඉච්චෙතෙ ආදෙසා හොන්ති යථාක්කමං අංම්හි විභත්තිම්හිති අත්ථො.",
