    "sutta_name": "236. තුම්හස්ස තුවං ත්වමංම්හි",
    "sutta_meaning": "**සවිභත්තිස්ස**, විභක්ති සහිත වූ; **තුම්හස්ස**, (සියලුම) තුම්හ ශබ්දයට; **අංම්හි**, අං විභක්ති පරකල්හි; **තුවං ත්වං**,තුවං ත්වං යන ආදේශ දෙක පිළිවෙළින් වෙත්.",
    "sutta_type": "ආදෙසවිධාන සූත්‍ර (කච්. 146)",
