    "anuvattana": "සවිභත්තිස්ස - 243 (ක.120) අම්හස්ස මමං සවිභත්තිස්ස සෙ",
    "vutti": "සබ්බස්ස තුම්හසද්දස්ස සවිභත්තිස්ස තුවංත්වංඉච්චෙතෙ ආදෙසා හොන්ති අංම්හි විභත්තිම්හි. තුවං ත්වං.",
    "vutti_sanna": "**අංම්හි විභත්තිම්හි**, අං විභක්තිය පරකල්හි; **සවිභත්තිස්ස**, එම අං විභක්තිය හා සහිත වූ; **සබ්බස්ස තුම්හසද්දස්ස**, සියලු ම තුම්හ ශබ්දයට; **තුවං ත්වං ඉති**, තුවං ත්වං යන; **එතෙ ආදෙසා**, මේ ආදේශයෝ; **හොන්ති**, වෙත්; **තුවං ත්වං**, තුවං ත්වං යනු වේ.",
