    "sutta_meaning": "**තුම්හාම්හෙහි**, තුම්හ අම්හ ශබ්දයන් කෙරෙන් පර වූ; **අප්පඨමො**, ප්‍රථමා විභක්ති නොවූ; **යො**, යොවිභක්ති තෙමේ; **වා**, විකල්පයෙන්; **ආකං**, ආකං යනාදේශ වේ.",
