    "sutta_name": "238. නාම්හි තයා මයා",
    "sutta_meaning": "**සවිභත්තීනං**, විභක්ති සහිත වූ; තුම්හාම්හානං (සියලුම) තුම්හ අම්හ ශබ්දයන්ට; **නාම්හි**, නාවිභක්තීපර කල්හි; **තයාමයා**, තයා මයා යන ආදේශ දෙක පිළිවෙළින් වෙත්.",
    "sutta_type": "ආදෙසවිධාන සූත්‍ර (කච්. 145)",
