    "vutti_sanna": "**තයා තයි ඉති**, තයා තයි යන; **එතෙසං**, මේ ආදේශ දෙදෙනාගේ; **තකාරො**, තකාරය තෙම; **වා**, විකල්පයෙන්; **ත්වත්තං ආපජ්ජතෙ**, ත්වකාර බවට පැමිණේ — **ත්වයා තයා**, ත්වයා, තයා යනාදිය වේ. **මයා, තුම්හෙහි තුම්හෙභි, අම්හෙහි අම්හෙභි**, (තෘතීයා රූප).",
