    "sutta_name": "241. තව මම සෙ",
    "sutta_meaning": "**සවිභත්තීනං**, විභක්ති සහිත වූ; **තුම්හාම්හානං**, (සියලුම) තුම්හඅම්හ ශබ්දයන්ට; **සෙ**, සවිභක්ති පරකල්හි; **තව මම**, තව මම යන ආදෙශ දෙක පිළිවෙළින් වෙත්.",
    "sutta_type": "ආදෙසවිධාන සූත්‍ර (කච්. 141)",
    "pada_cheda": "තව + මම + සෙ (තිපද සූත්‍රයකි)",
    "anuvattana": "සවිභත්තීනං - 243 (ක.120) අම්හස්ස මමං සවිභත්තිස්ස සෙ; තුම්හාම්හානං - 245 (ක.139) තුම්හම්හාකං තයි මයි",
    "vutti": "සබ්බෙසං තුම්හ අම්හසද්දානං සවිභත්තීනං යථාක්කමං තවමමඉච්චෙතෙ ආදෙසා හොන්ති සෙ විභත්තිම්හි, විකප්පෙනායං විජ්ඣන්තරස්ස විජ්ජමානත්තා.",
    "vutti_sanna": "**සෙ විභත්තිම්හි**, ස විභක්තිය පරකල්හි; **සවිභත්තීනං**, (එම විභක්තිය හා) සහිත වූ; **සබ්බෙසං තුම්හ අම්හ සද්දානං**, සියලු තුම්හ අම්හ ශබ්දයන්ට; **යථාක්කමං**, සූත්‍රයෙහි පඨිත ක්‍රමය නො හැර; **තව මම ඉති**, තව මම යන; **එතෙ ආදෙසා**, මේ ආදේශයෝ; **හොන්ති**, වෙත් — තුම්හ ශබ්දයට තව ද අම්හ ශබ්දයට මම ද වේ.<br><br>**අයං**, මේ විධිය; **විකප්පෙන**, විකල්පයෙනි; කිසේ හැඟේද යත්? **විජ්ඣන්තරස්ස විජ්ජමානත්තා**, සවිභක්ති පරකල්හි තුම්හ අම්හ ශබ්දයන්ට මෙයින් අන්‍ය විධියක්හුගේ විද්‍යමානත්වය හෙතුකොට ගෙනයි — තවමමාදේශයාගේ විකල්පය පිණිස වා ශබ්දයක් නැතද ‘තුය්හං මය්හඤ්ච’, ‘අම්හස්ස මමං සවිභත්තිස්ස සෙ’, ‘සස්සං’ යන සූත්‍රයන්ගෙන් ස විභක්ති පරකල්හි ම තුය්හං මය්හං යනාදි ආදේශාන්තරයන්ගේ විධානය හෙතුකොට ගෙන තවමමාදේශය විකල්පයෙන් වන්නේ ය.",
    "shadakara": {
      "sambandha_pali": "චතුත්ථීඡට්ඨෙකවචනෙ ‘සවිභත්තීනං, තුම්හාම්හාක’න්ති අධිකාරෙ සෙ තවමමආදෙසවිධානත්ථං ඉදමාහාති අයමිහ සම්බන්ධො.",
      "sambandha": "චතුර්ථී ෂෂ්ඨී එකවචනයෙහි ‘සවිභත්තීනං, තුම්හාම්හාකං’ අධිකාරයෙහි ස පර කල්හි තව, මම ආදේශ විධානය පිණිස මෙම සූත්‍රය වදාරන ලදී.",
      "pada_pali": "තව, මම, සෙති තීණි පදානි.",
      "pada": "තව, මම, සෙ යනුවෙන් පද තුනකි.",
      "padattha_pali": "සබ්බෙසං තුම්හඅම්හසද්දානං සවිභත්තීනං යථාක්කමං තව මම ඉච්චෙතෙ ආදෙසා හොන්ති සෙ විභත්තිම්හිති අත්ථො.",
      "padattha": "ස විභක්තිය පර කල්හි විභක්ති සහිත තුම්හ අම්හ ශබ්දයන්ට පිළිවෙළින් තව, මම ආදේශයෝ වෙත් යනු අර්ථයි.",
      "padaviggaha_pali": "තවො ච මමො ච තවමමා.",
      "padaviggaha": "තව ද මම ද තවමම නම්.",
      "chodana_pali": "වාසද්දාභාවෙපි කථමිදං විකප්පෙන?",
      "chodana": "වා ශබ්දයක් නැති කල්හිද මෙය විකල්පයෙන් වන්නේ කෙසේද?",
      "parihara_pali": "විධ්‍යන්තරස්ස විජ්ජමානත්තා — තුය්හං, මය්හං, තුම්හං, අම්හං, මමං.",
      "parihara": "අන්‍ය විධි ඇති හෙයිනි — තුය්හං, මය්හං, තුම්හං, අම්හං, මමං."
    },
    "extended_commentary": "<p>අයං මේ විධිය; විකප්පෙන, විකල්පයෙනි; හේ කිසේ හැඟේද යත්? විජ්ඣන්තරස්ස විජ්ජමානත්තා, සවිභක්ති පරකල්හි තුම්හ අම්හ යන ශබ්දයන්ට මෙයින් අන්‍ය විධියක්හුගේ විද්‍යාමානත්වය හෙතුකොට ගෙන යි-තවමමාදෙශයාගේ විකල්පය පිණිස වා ශබ්දයක් නැතද තුය්හං මය්හංච 2 - 2 - 23 අම්හස්ස මමං සවිභත්තිස්ස සෙ 2 2 1 සස්සං 2 – 3 –3 යන මෙතෙක් සූත්‍රයෙන් ස-විභක්ති පරකල්හි ම තුම්හ අම්හ යන ශබ්දයන්ට තුය්හංමය්හං යනාදි ආදෙශාන්තරයන්ගේ විධානය හෙතු කොට ගෙන තවමමාදේශය විකල්පයෙන් වන්නේය යි සේ යි.</p>",
