    "sutta_name": "242. තුය්හං මය්හඤ්ච",
    "sutta_meaning": "**සවිභත්තීනං**, විභක්ති සහිත වූ; තුම්හාම්හානං (සියලුම) තුම්හ අම්හ ශබ්දයන්ට; සෙ; සවිභක්ති පරකල්හි; **තුය්හං මය්හං ච**, තුය්හං මය්හං යන ආදේශ දෙකද පිළිවෙළින් වෙත්.",
    "sutta_type": "ආදෙසවිධාන සූත්‍ර (කච්. 142)",
    "pada_cheda": "තුය්හං + මය්හං + ච (තිපද සූත්‍රයකි)",
    "anuvattana": "සවිභත්තීනං - 243 (ක.120) අම්හස්ස මමං සවිභත්තිස්ස සෙ; තුම්හාම්හානං - 245 (ක.139) තුම්හම්හාකං තයි මයි; සෙ - 241 (ක.141) තවමම සෙ",
    "vutti": "‘සෙ’ති වත්තතෙ.<br><br>සබ්බෙසං තුම්හ අම්හසද්දානං සවිභත්තීනං යථාක්කමං තුය්හංමය්හංඉච්චෙතෙ ආදෙසා ච හොන්ති සෙ විභත්තිම්හි.<br>තුය්හං, මය්හං වා දීයතෙ.",
    "vutti_sanna": "**සෙති වත්තතෙ**, ‘තවමම සෙ’ සූත්‍රයෙන් සෙ යනු මතු සූත්‍රයට වැටේ.<br><br>**තුය්හඤ්ච මය්හඤ්ච තුය්හංමය්හං** — මෙහි ච ග්‍රහණය සෙ ග්‍රහණානුකර්ෂණය පිණිසයි. **සෙ විභත්තිම්හි**, ස විභක්තිය පරකල්හි; **සවිභත්තීනං**, (එම විභක්තිය හා) සහිත වූ; **සබ්බෙසං තුම්හ අම්හ සද්දානං**, සියලු තුම්හ අම්හ ශබ්දයන්ට; **තුය්හං මය්හං ඉති**, තුය්හං මය්හං යන; **එතෙ ආදෙසා**, මේ ආදේශයෝ; **යථාක්කමං**, සූත්‍රයෙහි පඨිත ක්‍රමය නො හැර; **හොන්ති**, වෙත් — **තව මම තුය්හං මය්හං වා දීයතෙ**.",
    "shadakara": {
      "sambandha_pali": "‘සෙ’ති වත්තමානෙ සවිභත්තීනං තුම්හම්හසද්දානං තුය්හංමය්හංආදෙසවිධානත්ථං ඉදමාහාති අයමිහ සම්බන්ධො.",
      "sambandha": "‘සෙ’ අනුවර්තනය වන කල්හි විභක්ති සහිත තුම්හ අම්හ ශබ්දයන්ට තුය්හං, මය්හං ආදේශ විධානය පිණිස මෙම සූත්‍රය වදාරන ලදී.",
      "pada_pali": "තුය්හං, මය්හං, චති තීණි පදානි.",
      "pada": "තුය්හං, මය්හං, ච යනුවෙන් පද තුනකි.",
      "padattha_pali": "සබ්බෙසං තුම්හඅම්හසද්දානං සවිභත්තීනං යථාක්කමං තුය්හං මය්හං ඉච්චෙතෙ ආදෙසා ච හොන්ති සෙ විභත්තිම්හිති අත්ථො.",
      "padattha": "ස විභක්තිය පර කල්හි විභක්ති සහිත තුම්හ අම්හ ශබ්දයන්ට පිළිවෙළින් තුය්හං, මය්හං ආදේශයෝ ද වෙත් යනු අර්ථයි.",
      "padaviggaha_pali": "තුය්හඤ්ච මය්හඤ්ච තුය්හංමය්හං.",
      "padaviggaha": "තුය්හං ද මය්හං ද තුය්හංමය්හං නම්.",
      "chodana_pali": "චසද්දො කිමත්ථො?",
      "chodana": "ච ශබ්දය කුමක් පිණිසද?",
      "parihara_pali": "සෙගහණානුකඩ්ඪනත්ථො.",
      "parihara": "‘සෙ’ ග්‍රහණය අනුකර්ෂණය පිණිසයි."
    },
