    "sutta_meaning": "**පදතො**, පදයා කෙරෙන් පර වූ; **සවිභත්තීනං**, විභක්ති සහිත වූ; **තුම්හාම්හානං**, තුම්හ අම්හ ශබ්දයන්ට; **අංම්හි**, අංවිභක්ති පරකල්හි; **තෙමෙ**, තෙමෙ යන ආදේශයෝ; **න**, නොවෙත්.",
