    "anuvattana": "සවිභත්තීනං - 243 (ක.120) අම්හස්ස මමං සවිභත්තිස්ස සෙ; තුම්හාම්හානං - 245 (ක.139) තුම්හම්හාකං තයි මයි; පදතො - 241 (ක.147) පදතො දුතියාචතුත්ථීඡට්ඨීසු වොනො; තෙමෙ - 247 (ක.148) තෙමෙකවචනෙසු ච",
    "vutti": "‘තෙ මෙ’ති වත්තතෙ.<br><br>සබ්බෙසං තුම්හ අම්හසද්දානං සවිභත්තීනං පදස්මා පරෙසං තෙ මෙආදෙසා න හොන්ති අංම්හි විභත්තිම්හි.<br>පස්සෙය්‍ය තං වස්සසතං ආරොග්‍යං. සො මමබ්‍රවීති.",
    "vutti_sanna": "**තෙ මෙති වත්තතෙ**, ‘තෙමෙකවචනෙසු ච’ සූත්‍රයෙන් තෙ මෙ යනු වැටේ.<br><br>**අංම්හි විභත්තිම්හි**, අං විභක්තිය පරකල්හි; **පදස්මා පරෙසං**, පෙදෙන් පර වූ; **සවිභත්තීනං**, එම අං විභක්තිය හා සහිත වූ; **සබ්බෙසං තුම්හ අම්හ සද්දානං**, සියලු තුම්හ අම්හ ශබ්දයන්ට; **තෙ මෙ ආදෙසා න හොන්ති**, තෙ මෙ යන ආදේශයෝ නො වෙත් — **පස්සෙය්‍ය තං වස්සසතං ආරොග්‍යං**, අවුරුදු සියයක් මුළුල්ලෙහි අරෝගී වූ තා දක්නේ ය; **සො මමබ්‍රවි**, හෙතෙම මට කීය (පස්සෙය්‍ය යනු තං පදයාගේ පෙදෙන් පර භාවයද ද්විතීයාන්ත භාවයද හඟවන පිණිසයි).",
