      "parihara_pali": "‘තෙමෙකවචනෙසු චා’ති චසද්දෙන දුතියෙකවචනෙපි පසඞ්ගනිවාරණත්ථං — පස්සෙය්‍ය තං, සො මමබ්‍රවි.",
      "parihara": "‘තෙමෙකවචනෙසු ච’ හි ච ශබ්දයෙන් ද්විතීයා එකවචනයෙහිද ප්‍රසඞ්ගය වැළැක්වීම පිණිසයි — පස්සෙය්‍ය තං, සො මමබ්‍රවි."
