    "sutta_name": "249. වා තතියෙ ච",
    "sutta_meaning": "**පදතො**, පදයා කෙරෙන් පර වූ; **සවිභත්තීනං**, විභක්ති සහිත වූ; **තුම්හාම්හානං**, (සියලුම ) තුම්හඅම්හ ශබ්දයන්ට; **තතියෙකවචනෙ ච**, තෘතීයා එක වචනය පරකල්හිද; **තෙමෙ**, තෙ මෙ යන ආදේශයෝ; **වා**, විකල්පයෙන් වෙත්.",
    "sutta_type": "ආදෙසවිධාන සූත්‍ර (කච්. 150)",
    "pada_cheda": "වා + තතියෙ + ච (තිපද සූත්‍රයකි)",
    "anuvattana": "සවිභත්තීනං - 243 (ක.120) අම්හස්ස මමං සවිභත්තිස්ස සෙ; තුම්හාම්හානං - 245 (ක.139) තුම්හම්හාකං තයි මයි; පදතො - 241 (ක.147) පදතො දුතියාචතුත්ථීඡට්ඨීසු වොනො; තෙමෙ- එකවචනෙ - 247 (ක.148) තෙමෙකවචනෙසු ච",
    "vutti": "‘තෙමෙකවචනෙ’ති වත්තතෙ.<br><br>සබ්බෙසං තුම්හ අම්හසද්දානං සවිභත්තීනං පදස්මා පරෙසං තෙ මෙ ආදෙසා හොන්ති වා යථාක්කමං තතියෙකවචනෙ පරෙ.<br>කතං තෙ පාපං, කතං තයා පාපං,<br>කතං මෙ පුඤ්ඤං, කතං මයා පුඤ්ඤං.",
    "vutti_sanna": "**තෙමෙකවචනෙති වත්තතෙ**, ‘තෙමෙකවචනෙසු ච’ සූත්‍රයෙන් තෙමෙකවචනෙ යනු මතු සූත්‍රයට වැටේ. **තතියෙ ච** යන මෙහි ච ශබ්දය තෙමෙ අනුකර්ෂණය පිණිසයි.<br><br>**තතියෙකවචනෙ පරෙ**, තෘතීයා එකවචනය පරකල්හි; **පදස්මා පරෙසං**, පෙදෙන් පර වූ; **සවිභත්තීනං**, ඒ නා විභක්තිය හා සහිත වූ; **සබ්බෙසං තුම්හ අම්හ සද්දානං**, සියලු තුම්හ අම්හ ශබ්දයන්ට; **යථාක්කමං**, පඨිතානුක්‍රමයෙන්; **වා**, විකල්පයෙන්; **තෙ මෙ ආදෙසා හොන්ති**, (පූර්වපදය හා එකවාක්‍යභාවයක් ඇති කල්හි) තෙ මෙ යන ආදේශයෝ වෙත් — **කතං තෙ පාපං, කතං තයා පාපං**, තා විසින් පවක් කරන ලදී; **කතං මෙ පුඤ්ඤං, කතං මයා පුඤ්ඤං**, මා විසින් පිනක් කරන ලදී (කතං යනු තෙ ආදි පදයන්ගේ පෙදෙන් පරබවද තෘතීයාන්ත බවද හඟවන පිණිසයි).",
