    "sutta_name": "250. බහුවචනෙසු වො නො",
    "sutta_meaning": "**පදතො**, පදයා කෙරෙන් පරවූ; **සවිභත්තීනං**, විභක්ති සහිත වූ; **තුම්හාම්හානං**, තුම්භ අම්හ ශබ්දයන්ට; **තතියා බහුවචනෙසු**, තෘතීයා බහු වචනයන් පරකල්හි; **වා**, විකල්පයෙන්; **වොනො**, පිළිවෙළින් වොනො යන ආදේශයෝ වෙත්.",
    "sutta_type": "ආදෙසවිධාන සූත්‍ර (කච්. 151)",
    "pada_cheda": "බහුවචනෙසු + වොනො (ද්විපද සූත්‍රයකි)",
    "anuvattana": "සවිභත්තීනං - 243 (ක.120) අම්හස්ස මමං සවිභත්තිස්ස සෙ; තුම්හාම්හානං - 245 (ක.139) තුම්හම්හාකං තයි මයි; පදතො - 241 (ක.147) පදතො දුතියාචතුත්ථීඡට්ඨීසු වොනො; වා-තතියා - 249 (ක.150) වා තතියෙ ච; සවිභත්තීනං - 243 (ක.120) අම්හස්ස මමං සවිභත්තිස්ස සෙ",
    "vutti": "‘වා, තතියෙ’ති ච වත්තතෙ.<br><br>සබ්බෙසං තුම්හ අම්හසද්දානං සවිභත්තීනං පදස්මා පරෙසං වො නොආදෙසා හොන්ති වා යථාක්කමං තතියාබහුවචනෙ පරෙ.<br>කතං වො කම්මං, කතං නො කම්මං.<br>බහුවචනනිද්දෙසෙන ක්වචි යොම්හි පඨමෙ ච වො නො හොන්ති.<br>ගාමං වො ගච්ඡෙය්‍යාථ,<br>ගාමං නො ගච්ඡෙය්‍යාම.",
    "vutti_sanna": "**වා තතියෙති ච වත්තතෙ**, ‘වා තතියෙ ච’ සූත්‍රයෙන් වා යනුද තතියෙ යනුද මතු සූත්‍රයට වැටේ.<br><br>**තතියාබහුවචනෙ පරෙ**, තෘතීයා බහුවචනය පරකල්හි; **පදස්මා පරෙසං**, පෙදෙන් පර වූ; **සවිභත්තීනං**, එම තෘතීයා බහුවචන විභක්තිය හා සහිත වූ; **සබ්බෙසං තුම්හ අම්හ සද්දානං**, සියලු තුම්හ අම්හ ශබ්දයන්ට; **යථාක්කමං**, පඨිතානුක්‍රමය නොඉක්මවා; **වා**, විකල්පයෙන්; **වො නො ආදෙසා හොන්ති**, (පූර්වපදයාගේ එකවාක්‍යභාවයක් ඇති කල්හි) වො නො යන ආදේශයෝ වෙත් — **කතං වො කම්මං**, තොප විසින් කර්මය කරන ලදී; **කතං නො කම්මං**, අප විසින් කර්මය කරන ලදී.<br><br>**බහුවචනනිද්දෙසෙන**, බහුවචනය වශයෙන් දැක්වීමෙන්; **ක්වචි**, කිසි විෂයෙක්හි; **පඨමෙ යොම්හි ච**, ප්‍රථමා යො පරකල්හිද; **වො නො හොන්ති**, වො නො ආදේශ වෙත් (තෘතීයා බහුවචනයාගේ ස්වරූපයෙන් එකත්වය හෙතුකොට ගෙන ‘බහුවචනෙ’ යි එකවචනයෙන් කියනු නො කොට ‘බහුවචනෙසු’ යි බහුවචනාන්ත කොට සූත්‍රකාරයන් දැක්වූ සාමර්ථ්‍යයෙන්) — **ගාමං වො ගච්ඡෙය්‍යාථ**, තෙපි ගමට යවු; **ගාමං නො ගච්ඡෙය්‍යාම**, අපි ගමට යමු.",
