      "padattha": "තෘතීයා බහුවචනය පර කල්හි පෙදෙන් පර වූ විභක්ති සහිත තුම්හ අම්හ ශබ්දයන්ට පිළිවෙළින් විකල්පයෙන් වො, නො ආදේශයෝ වෙත් යනු අර්ථයි.",
