    "sutta_name": "254. එකාදිතො දස්ස ර සඞ්ඛ්‍යානෙ",
    "sutta_meaning": "**සංඛ්‍යානෙ**, ගණනෙහි; **එකාදිතො**, එක ශබ්දාදීන් කෙරෙන් (පර වූ) දස්ස, දසශබ්දයාගේ දකාරය තෙම; **වා**, විකල්පයෙන්; **ර**, රකාරය වේ.",
    "sutta_type": "ආදෙසවිධාන සූත්‍ර (කච්. 383)",
    "pada_cheda": "එකාදිතො + දස්ස + ර + සඞ්ඛ්‍යානෙ (චතුප්පද සූත්‍රයකි)",
    "anuvattana": "වා - 408 (ක.376) ස ඡස්ස වා",
    "vutti": "‘වා’ති වත්තතෙ.<br><br>එකාදිතො සඞ්ඛ්‍යාතො පරස්ස දසස්ස ආදිස්ස දස්ස රකාරො හොති වා සඞ්ඛ්‍යානෙ. සෙසං සමං. එකාරස, එකාදස.",
    "vutti_sanna": "**වාති වත්තතෙ**, ‘ස ඡස්ස වා’ සූත්‍රයෙන් වා යනු මණ්ඩූකගතියෙන් වැටේ. **දසස්සාති වත්තබ්බෙ දස්සාති** — දසස්ස රෙ යි කියයුතු කල්හි ‘දස්ස ර’ යි ෂෂ්ඨ්‍යෙකවචන ලොපයෙන් කියන ලදැයි දතයුතු.<br><br>**එකාදිතො සඞ්ඛ්‍යාතො පරස්ස**, එක ශබ්දාදි වූ සංඛ්‍යාවාචී ශබ්දයා කෙරෙන් පර වූ; **සඞ්ඛ්‍යානෙ වත්තමානස්ස දසස්ස**, සංඛ්‍යානයෙහි වැටෙන්නා වූ දස ශබ්දයාගේ; **ආදිස්ස දකාරස්ස**, ආදි වූ දකාරය හට; **වා**, විකල්පයෙන්; **රකාරො හොති**, රකාරයෙක් වේ. **සෙසං සමං**, සෙසු කාර්යයෝ පඤ්ච ශබ්දයා හා සම යි — එකාරස, එකාදස.<br><br>එකාරස, එකාදස යනු වේ — එකාරසාදි උදාහරණයෙහි සමාස සොට විභක්තිලොපය කරන ලද කල්හි ච ශබ්දයන්ට හෝ අධිකශබ්දය හට හෝ අප්‍රයෝග වේ; මත්තෙහිද මෙසේමැයි.",
    "shadakara": {
      "sambandha_pali": "‘වා’ති වත්තමානෙ එකාදිතො පරස්ස දසසද්දස්ස දකාරස්ස රකාරවිධානත්ථං ඉදමාහාති අයමිහ සම්බන්ධො.",
      "sambandha": "‘වා’ අනුවර්තනය වන කල්හි එකාදි සංඛ්‍යාවන් කෙරෙන් පර දස ශබ්දයේ දකාරයට රකාරය විධානය පිණිස මෙම සූත්‍රය වදාරන ලදී.",
      "pada_pali": "එකාදිතො, දස්ස, ර, සඞ්ඛ්‍යානෙති චත්තාරි පදානි.",
      "pada": "එකාදිතො, දස්ස, ර, සඞ්ඛ්‍යානෙ යනුවෙන් පද සතරකි.",
      "padattha_pali": "එකාදිතො සඞ්ඛ්‍යාතො පරස්ස දසස්ස ආදිස්ස දස්ස රකාරො හොති වා සඞ්ඛ්‍යානෙති අත්ථො.",
      "padattha": "එකාදි සංඛ්‍යාව කෙරෙන් පර වූ සංඛ්‍යානයෙහි වැටෙන දස ශබ්දයේ ආදි දකාරයට විකල්පයෙන් රකාරය වේ යනු අර්ථයි.",
      "padaviggaha_pali": "එකො ආදි යස්සාති එකාදි, තතො එකාදිතො.",
      "padaviggaha": "එක ශබ්දය ආදි කොට ඇත්තේ එකාදි නම්; එයින් එකාදිතො.",
      "chodana_pali": "එකාදිතොති කිමත්ථං?",
      "chodana": "‘එකාදිතො’ යන්න කුමක් පිණිසද?",
      "parihara_pali": "අසඞ්ඛ්‍යාපුබ්බස්ස දසස්ස මා හොතූති; සඞ්ඛ්‍යානෙති — සංඛ්‍යාවිසයෙයෙව.",
      "parihara": "සංඛ්‍යාව පූර්ව නොවූ දස ශබ්දයට නොවීම පිණිසයි; ‘සඞ්ඛ්‍යානෙ’ යනු සංඛ්‍යා විෂයෙහිම වීම පිණිසයි."
    },
    "extended_commentary": "<p>ද්වි+~~යො~~ දස (ශබ්ද ප්‍රකෘති හා විභක්ති වෙන් කිරීම)</p><p>ද්වි-~~හි~~ + දස (ශබ්ද ප්‍රකෘති හා විභක්ති වෙන් කිරීම)</p>",
